{
  "claims": [
    {
      "anchor": "On Redis 3.2, a writable replica that sets a TTL with EXPIRE will leak the key",
      "claim_text": "On Redis 3.2, a writable replica that sets a TTL with EXPIRE will leak the key.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"},
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "3.2", "op": "<", "right": "4.0"},
      "reasoning": "Before 4.0, writable replicas cannot expire TTL keys, so keys leak."
    },
    {
      "anchor": "which still shows up in the key count and uses memory",
      "claim_text": "The leaked key still shows up in the key count and uses memory.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage states leaked key appears in count and uses memory."
    },
    {
      "anchor": "From Redis 4.0 RC3 on, writable replicas evict TTL keys like masters",
      "claim_text": "From Redis 4.0 RC3 on, writable replicas evict TTL keys like masters.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "4.0 RC3", "op": ">=", "right": "4.0 RC3"},
      "reasoning": "Passage states Redis 4.0 RC3 and greater evict TTL keys as masters do."
    },
    {
      "anchor": "except for keys in databases numbered above 63",
      "claim_text": "Writable replicas on Redis 4.0 RC3 and greater do not evict TTL keys in databases numbered above 63.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage states exception for keys in DB numbers greater than 63."
    },
    {
      "anchor": "with the default 16 databases that exception never applies",
      "claim_text": "With the default 16 databases, the exception for databases above 63 never applies.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Default 16 databases are all <=63, so exception cannot apply."
    },
    {
      "anchor": "On Redis 6, cascading sub-replicas receive exactly the same replication stream from the master",
      "claim_text": "On Redis 6, cascading sub-replicas receive exactly the same replication stream from the master.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P1.S4", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "6", "op": ">=", "right": "4.0"},
      "reasoning": "Since Redis 4.0, sub-replicas receive identical stream; Redis 6 qualifies."
    },
    {
      "anchor": "On Redis 3.0, by contrast, local writes on an intermediate replica are propagated to its sub-replicas",
      "claim_text": "On Redis 3.0, local writes on an intermediate replica are propagated to its sub-replicas.",
      "kind": "logic",
      "sure": false,
      "evidence": [
        {"sid": "P5.S0", "rel": "refutes"}
      ],
      "check": {"kind": "version", "left": "3.0", "op": "<", "right": "4.0"},
      "reasoning": "Passage says since 4.0 writes are local only; it does not state pre-4.0 behavior, so claim is unsupported and likely contradicted."
    },
    {
      "anchor": "As of Redis 7.0 there are still legitimate use cases that require writable replicas",
      "claim_text": "As of Redis 7.0 there are still legitimate use cases that require writable replicas.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S1", "rel": "refutes"}
      ],
      "check": {"kind": "version", "left": "7.0", "op": ">=", "right": "7.0"},
      "reasoning": "Passage says as of 7.0 these use cases are obsolete."
    },
    {
      "anchor": "Requiring at least N connected replicas guarantees that every write reaches a replica",
      "claim_text": "Requiring at least N connected replicas guarantees that every write reaches a replica.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage states it is not possible to ensure replica received a given write."
    },
    {
      "anchor": "with a maximum lag of 10 seconds the data-loss window is bounded to about 10 seconds",
      "claim_text": "With a maximum lag of 10 seconds, the data-loss window is bounded to about 10 seconds.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P8.S2", "rel": "entails"},
        {"sid": "P9.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Configuring max lag bounds data-loss window to that number of seconds."
    },
    {
      "anchor": "WAIT does not turn Redis into a CP system",
      "claim_text": "WAIT does not turn Redis into a CP system.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage explicitly states WAIT does not make Redis a CP system."
    }
  ]
}
